      WORKER_PRIMARY_PERIOD_PROJECT_ACCESS_REQUIRED: "\u092A\u094D\u0930\u093E\u0925\u092E\u093F\u0915 \u092A\u094D\u0930\u094B\u091C\u0947\u0915\u094D\u091F \u092C\u0926\u0932\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092A\u094D\u0930\u092D\u093E\u0935\u093F\u0924 \u092A\u094D\u0930\u094B\u091C\u0947\u0915\u094D\u091F\u094B\u0902 \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u0906\u0935\u0936\u094D\u092F\u0915 \u0939\u0948\u0964",
      ATTENDANCE_EXCEPTION_DUPLICATE: "\u0907\u0938 \u0915\u093E\u092E\u0917\u093E\u0930 \u0914\u0930 \u0924\u093E\u0930\u0940\u0916 \u0915\u0947 \u0932\u093F\u090F \u0939\u093E\u091C\u093C\u093F\u0930\u0940 \u0905\u092A\u0935\u093E\u0926 \u092A\u0939\u0932\u0947 \u0938\u0947 \u0939\u0948\u0964 \u0930\u0940\u092B\u093C\u094D\u0930\u0947\u0936 \u0915\u0930\u0915\u0947 \u0909\u0938\u0940 \u0915\u094B \u0938\u0902\u092A\u093E\u0926\u093F\u0924 \u0915\u0930\u0947\u0902\u0964",
